// Normaliza o payload da uazapi (testado c/ v2.1.8). messageType vem como
// 'ImageMessage'/'ExtendedTextMessage' etc. — detectamos imagem por regex.
// Se a sua instância mudar nomes de campos, ajuste aqui (README > 'Verificar
// o mapeamento do webhook').
const raiz = $input.first().json;
const b = raiz.body || raiz;
const m = b.message || b.data || b;

const chatid = m.chatid || m.chatId || (m.key && m.key.remoteJid) || m.from || '';
const isGroup = Boolean(m.isGroup) || String(chatid).includes('@g.us');

// Remetente: NÃO usar m.owner (é o número da própria instância/bot).
const remetente = m.sender || m.participant || (m.key && m.key.participant) || m.senderNumber || (isGroup ? '' : chatid) || '';
const fromMe = Boolean(m.fromMe != null ? m.fromMe : (m.key && m.key.fromMe));

const tipoRaw = m.messageType || m.type || '';
const isImagem = /image/i.test(String(tipoRaw)) || Boolean(m.image);

const mime = m.mimetype || (m.image && m.image.mimetype) || 'image/jpeg';
// base64 da imagem (sem prefixo data:). Se sua instância NÃO manda base64 no
// webhook, adicione um nó HTTP para baixar a mídia antes deste ponto.
let imagem_base64 = m.mediaBase64 || m.base64 || (m.image && m.image.base64) || (m.content && m.content.base64) || m.buffer || '';
if (typeof imagem_base64 === 'string' && imagem_base64.startsWith('data:')) {
  imagem_base64 = imagem_base64.split(',').pop();
}

return [{ json: { remetente, grupo: isGroup ? chatid : '', fromMe, messageType: isImagem ? 'image' : String(tipoRaw), mime, imagem_base64 } }];
